shell_commands:
cat << 'EOF' > /tmp/add_test.js
const fs = require('fs');
const content = fs.readFileSync('/var/tmp/loop-bench/runs/471882b8da61/workspace/target/src/orchestration/chatOrchestrator.test.ts', 'utf8');

const newTest = `
    it('wraps a non-Error rejection in an Error to pass to onError, while propagating the original rejection', async () => {
      let receivedError: Error | undefined;
      const hooks: OrchestratorHooks = {
        onError: async (_session, error) => {
          receivedError = error;
        },
      };

      const orchestrator = createChatOrchestrator(
        createErrorProvider('just a string' as unknown as Error),
        promptBuilder,
        undefined,
        {hooks}
      );

      let thrown: unknown;
      try {
        await orchestrator.processMessage(createSession('hello'));
      } catch (e) {
        thrown = e;
      }

      expect(thrown).toBe('just a string');
      expect(receivedError).toBeInstanceOf(Error);
      expect(receivedError?.message).toBe('just a string');
      expect((receivedError as Error & {cause?: unknown})?.cause).toBe('just a string');
    });
`;

const updated = content.replace(
  "    it('error still propagates after onError hook', async () => {",
  newTest + "\n    it('error still propagates after onError hook', async () => {"
);
fs.writeFileSync('/var/tmp/loop-bench/runs/471882b8da61/workspace/target/src/orchestration/chatOrchestrator.test.ts', updated);
EOF
node /tmp/add_test.js

